node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});
// 1. missing required
let v = ajv.compile({type:'object', properties:{location:{type:'string'}}, required:['location']});
console.log('valid={} :', v({}), JSON.stringify(v.errors));
// 2. wrong type
console.log('valid={ssn:123} :', v({ssn: 123456789}), JSON.stringify(v.errors));
// 3. invalid type keyword at compile
try { ajv.compile({type:'object', properties:{location:{type:'not-a-json-schema-type'}}}); console.log('compile: NO THROW'); }
catch (e) { console.log('compile threw:', e.message.slice(0,140)); }
// 4. extra property pass-through
console.log('extra:', v({location:'Paris', extra: 1}));
// 5. unknown keyword tolerated with strict:false
try { const w = ajv.compile({type:'object', properties:{a:{type:'string', weirdKeyword: true}}, required:['a']}); console.log('unknown kw compiled, valid:', w({a:'x'})); } catch(e){ console.log('unknown kw threw:', e.message.slice(0,100)); }
"

